local _, WFJ = ...
WFJ.Data.add("book", {
  ["05235a8f14e33311"] = { "Lord Ebonlocke,\n\nla municipalità di ⟦Lakeshire=Borgolago⟧ chiede umilmente l'aiuto dei Guardiani della Notte. Siamo assediati sia dagli orchi ⟦Blackrock=Roccianera⟧ sia dagli gnoll Mantombroso di Morganth. Non vi manderei questa richiesta se la nostra situazione non fosse grave. Attendiamo aiuti da ⟦Stormwind=Roccavento⟧, ma finché non arriveranno vi supplico di darci il vostro sostegno. Se il regno verrà violato, l'intera umanità sarà in pericolo.\n\n⟦Magistrate Solomon=Magistrato Solomon⟧", "." },
  ["0596bc2473a0b04f"] = { "Benché le origini esatte dell'universo caotico restino oscure, è chiaro che una razza di esseri potenti sorse per portare ordine nei vari mondi e garantire un futuro sicuro agli esseri che ne avrebbero seguito le orme.\n\nI Titani, colossali dèi dalla pelle metallica giunti dai confini remoti del cosmo, si fecero avanti e si misero all'opera sui mondi che incontravano. Plasmarono la forma dei loro mondi innalzando possenti montagne e scavando vasti mari.", "." },
  ["05978be0a3c43b68"] = { "Ma dopo settimane senza notizie la mia pazienza vacillò e, informandomi ulteriormente presso Dalaran, appresi che la sanguinite non era mai arrivata ai miei colleghi. Il mio corriere si era in qualche modo perso lungo la strada, e il pendente di sanguinite era andato perduto con lui!\n\nÈ una notizia grave: anche se Kegan e i suoi seguaci hanno ancora campioni di sanguinite su cui possiamo fare esperimenti, temo che il pendente possa finire in mani poco raccomandabili.", "." },
  ["0597c4816dbb3003"] = { "Lasciandosi alle spalle la sua fortuna e la sua prestigiosa posizione politica, Kel'Thuzad abbandonò le vie del Kirin Tor e lasciò Dalaran per sempre. Spronato dalla voce insistente del Re dei Lich nella sua mente, vendette i suoi vasti possedimenti e mise al sicuro le sue ricchezze. Viaggiando da solo per molte leghe di terra e di mare, raggiunse infine le coste ghiacciate della Nordania.", "." },
  ["05cc8fafcab8c713"] = { "Kel'Thuzad tornò a Lordaeron sotto mentite spoglie e, nell'arco di tre anni, usò la sua fortuna e il suo intelletto per riunire una confraternita clandestina di uomini e donne che la pensavano come lui. La confraternita, che egli chiamò Cult of the Damned, prometteva ai suoi accoliti uguaglianza sociale e vita eterna su Azeroth in cambio del loro servizio e della loro obbedienza a Ner'zhul.", "." },
  ["05d0308e1328d6e9"] = { "Il tempo passò, e Aegwynn diede alla luce suo figlio in un boschetto appartato. Chiamò il bambino Medivh, che nella lingua degli alti elfi significa «custode dei segreti», convinta che crescendo sarebbe diventato il prossimo Guardiano. Purtroppo lo spirito maligno di Sargeras, che si era nascosto dentro di lei, si era impossessato del bambino indifeso quando era ancora nel suo grembo. Aegwynn non aveva idea che il nuovo Guardiano del mondo fosse già posseduto dalla sua più grande nemesi.", "." },
  ["05f9ea7d3cd8e9d6"] = { "Rapporto di missione degli Inseguitori della Morte\n\nAgenti: Rane Yorick, Quinn Yorick, Erland McKree\n\nMissione primaria: compiere una ricognizione nella Selva Pinargento settentrionale e determinare il livello di minaccia della fauna e del Flagello.", "." },
})
